use crate::money::Minor;

/// Parse a decimal string at a declared scale, ROUNDING the last digit.
///
/// Rounding rather than truncating is the whole difference from `money::parse_minor`, and it is not
/// a nicety: truncation moves every price the same direction, so it does not cancel out over a
/// series the way a rounding error does.
pub fn parse_at_scale(raw: &str, minor_per_unit: i64) -> Result<Minor, String> {
    let t = raw.trim();
    if t.is_empty() {
        return Err("empty price".to_string());
    }
    let (t, neg) = match t.strip_prefix('-') {
        Some(rest) => (rest, true),
        None => (t, false),
    };
    let mut whole = String::new();
    let mut frac = String::new();
    let mut seen_dot = false;
    for c in t.chars() {
        match c {
            '.' if !seen_dot => seen_dot = true,
            '.' => return Err(format!("more than one decimal point in {raw:?}")),
            ',' | ' ' | '$' => {}
            c if c.is_ascii_digit() => {
                if seen_dot {
                    frac.push(c)
                } else {
                    whole.push(c)
                }
            }
            c => return Err(format!("unexpected {c:?} in price {raw:?}")),
        }
    }
    if whole.is_empty() && frac.is_empty() {
        return Err(format!("no digits in price {raw:?}"));
    }
    let w: i64 = if whole.is_empty() { 0 } else { whole.parse().map_err(|_| format!("price out of range: {raw:?}"))? };
    // Build the fraction as a rational at the target scale, then round the remainder.
    let digits = frac.len() as u32;
    let f: i64 = if frac.is_empty() { 0 } else { frac.parse().map_err(|_| format!("bad fraction in {raw:?}"))? };
    let pow = 10i64.checked_pow(digits).ok_or_else(|| format!("too many decimal places in {raw:?}"))?;
    let scaled_frac = if pow == 0 { 0 } else { (f * minor_per_unit * 2 / pow).div_euclid(2) + i64::from((f * minor_per_unit * 2 / pow).rem_euclid(2) != 0) };
    let minor = w.checked_mul(minor_per_unit).and_then(|x| x.checked_add(scaled_frac)).ok_or_else(|| format!("price out of range: {raw:?}"))?;
    Ok(if neg { -minor } else { minor })
}
